// ─── Configuración ────────────────────────────────────────────────────────
// LinkedIn solo expone analíticas de PÁGINAS DE EMPRESA, no de perfiles
// personales, y a través de la Community Management API, que exige aprobación
// en el Partner Program de LinkedIn.
//
// ORG_ID es el identificador numérico de tu página:
//   https://www.linkedin.com/company/<nombre>/  →  Admin → Page info
const AJUSTES = {
  ORG_ID: 'PON_AQUI_TU_ORG_ID',
  // Versión de la API en formato AAAAMM. La cabecera es obligatoria.
  LINKEDIN_VERSION: '202604',
  API_HOST: 'https://api.linkedin.com',
};

const env = (() => { try { return $env ?? {}; } catch { return {}; } })();
const ORG_ID = env.LINKEDIN_ORG_ID || AJUSTES.ORG_ID;
const VERSION = env.LINKEDIN_VERSION || AJUSTES.LINKEDIN_VERSION;
const HOST = env.LINKEDIN_API_HOST || AJUSTES.API_HOST;

if (ORG_ID === 'PON_AQUI_TU_ORG_ID') {
  throw new Error('Falta ORG_ID: rellénalo en el nodo Configuración o define LINKEDIN_ORG_ID.');
}

const ORG_URN = `urn:li:organization:${ORG_ID}`;

const RANGE_DAYS = { '7d': 7, '30d': 30, '90d': 90, '12m': 365 };
const range = $input.first().json.query?.range ?? '30d';
const days = RANGE_DAYS[range] ?? 30;

// LinkedIn espera milisegundos, no segundos como Meta.
const end = Date.now();
const start = end - days * 86400000;

return [{ json: { orgId: ORG_ID, orgUrn: ORG_URN, version: VERSION, host: HOST, range, days, start, end } }];

// Une página, seguidores y estadísticas en la forma que espera el panel.
const cfg = $('Configuración').first().json;
const org = $('Página').first().json ?? {};
const net = $('Seguidores').first().json ?? {};
const shares = $('Estadísticas de publicaciones').first().json ?? {};

const errors = [org.message, net.message, shares.message].filter(Boolean);

// La respuesta trae un elemento por intervalo; se suman todos.
const totals = { impressionCount: 0, clickCount: 0, likeCount: 0, commentCount: 0, shareCount: 0 };
let any = false;
for (const el of shares.elements ?? []) {
  const t = el.totalShareStatistics ?? el;
  for (const k of Object.keys(totals)) {
    if (typeof t[k] === 'number') { totals[k] += t[k]; any = true; }
  }
}

const interactions = totals.likeCount + totals.commentCount + totals.shareCount;
const engagement = any && totals.impressionCount ? (interactions / totals.impressionCount) * 100 : null;

const miles = (n) => String(n).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
const fmt = (n) => (n == null ? null
  : n >= 1e6 ? (n / 1e6).toFixed(2) + 'M'
  : n >= 1e3 ? (n / 1e3).toFixed(1) + 'K'
  : String(n));

const followers = typeof net.firstDegreeSize === 'number' ? net.firstDegreeSize : null;

const captions = { '7d': 'vs semana anterior', '30d': 'vs mes anterior',
                   '90d': 'vs trimestre anterior', '12m': 'vs año anterior' };

return [{ json: {
  source: 'linkedin',
  range: cfg.range,
  errors,
  account: {
    name: org.localizedName ?? null,
    handle: org.vanityName ? 'company/' + org.vanityName : null,
    audience: followers == null ? null : miles(followers) + ' seguidores',
  },
  kpis: {
    impresiones: { value: any ? fmt(totals.impressionCount) : null, caption: captions[cfg.range] },
    interaccion: { value: engagement == null ? null : engagement.toFixed(1) + '%', caption: 'interacciones / impresiones' },
    // El alta de seguidores del periodo vive en otro endpoint; aquí va el total.
    contactos: { value: followers == null ? null : fmt(followers), caption: 'seguidores de la página' },
    clicks: { value: any ? miles(totals.clickCount) : null, caption: 'clicks en las publicaciones' },
  },
} }];
